{
  "name": "opencode-image-vision",
  "version": "1.0.6",
  "type": "module",
  "description": "Image vision, OCR, and clipboard support for OpenCode - enables vision models for models that don't support image input",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    "./server": "./dist/index.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "image",
    "vision",
    "ocr",
    "clipboard",
    "pdf"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0"
  },
  "dependencies": {
    "openai": "^4.95.0",
    "pdf-parse": "^1.1.1"
  },
  "devDependencies": {
    "@types/node": "^22.14.1",
    "@types/pdf-parse": "^1.1.4",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build"
  },
  "license": "MIT"
}
